sys_ux_screen_condition.script:
(function validate(params) {
    // TODO: Add validations
    if (params.sysId == -1)
        return false;
    else {
        if (params.table == 'sn_risk_advanced_event') {

            var riskEvent = new GlideRecord('sn_risk_advanced_event');
            riskEvent.get(params.sysId);
            if (riskEvent.canRead()) {
                if (gs.getProperty('sn_risk_advanced.show_basel_attr_reports', false) == 'true') {
                    var primaryEntity = new GlideRecord('sn_grc_profile');
                    primaryEntity.get(riskEvent.primary_profile + '');
                    var baseBaselBusinessLine = primaryEntity.sn_risk_advanced_basel_business_line;

                    if (!baseBaselBusinessLine.nil()) {
                        return true;
                    }
                }


                var addedRisksRelatedToPrimaryEntity = new GlideRecord('sn_risk_advanced_m2m_event_risk');
                addedRisksRelatedToPrimaryEntity.addQuery('risk_event', riskEvent.getUniqueValue());
                addedRisksRelatedToPrimaryEntity.addQuery('risk.profile', riskEvent.primary_profile);
                addedRisksRelatedToPrimaryEntity.query();

                while (addedRisksRelatedToPrimaryEntity.next()) {
                    var curRiskStatement = addedRisksRelatedToPrimaryEntity.risk.statement;
                    if (!curRiskStatement.nil()) {
                        return true;
                    }
                }

                return false;
            } else
                return false;
        } else {
            return false;
        }
    }
})(inputProperties);
